class Stack:
    def __init__(self):
        self.items = []
    def push(self, val):
        self.items.append(val)
    def pop(self):
        return self.items.pop() if self.items else "VIDE"
    def peek(self):
        return self.items[-1] if self.items else "VIDE"
    def is_empty(self):
        return len(self.items) == 0
    def size(self):
        return len(self.items)

n = int(input())
s = Stack()
for _ in range(n):
    cmd = input().split()
    if cmd[0] == 'push':
        s.push(cmd[1])
    elif cmd[0] == 'pop':
