class Temperature:
    def __init__(self, celsius=0.0):
        self.celsius = celsius

    @property
    def celsius(self):
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if value < -273.15:
            raise ValueError("Invalide")
        self._celsius = float(value)

    @property
    def fahrenheit(self):
        return self._celsius * 9.0 / 5.0 + 32.0

val = float(input())
try:
    t = Temperature(val)
    print(f"{t.celsius:.2f}C = {t.fahrenheit:.2f}F" if t.celsius == -273.15 else f"{t.celsius:.1f}C = {t.fahrenheit:.1f}F")
except ValueError:
    print("Erreur")

