class SimpleDate:
    def __init__(self, day, month, year):
        self.day = int(day)
        self.month = int(month)
        self.year = int(year)

    @classmethod
    def from_iso(cls, iso_str):
        y, m, d = iso_str.strip().split('-')
        return cls(d, m, y)

    def __str__(self):
        return f"{self.day:02d}/{self.month:02d}/{self.year:04d}"

iso = input().strip()
d = SimpleDate.from_iso(iso)
print(d)

